scenes._print.mjs:
// 画法：木刻／麻胶版画，三色套印。
//
// 形不是"描边再填充"，是**一整块墨，再从上头刻掉要白的地方**：
//   mass()  画一块有刀口抖动的墨块，顺手沿着轮廓刻一道纸色的沟；
//   hatch() 平行排线，角度全片固定 42°（刀的方向不换，换的只有密度）；
//   ribbon()/figureBack() 是人身上的形，宽度收尖、边缘有缺口；
//   paper()  纸纤维垫底；dots() 是给"光"用的点阵（黄版压在纸上）。
//
// 这个文件只属于本片：不往引擎里加，也不改 kit/。

export const W = 1920;
export const H = 1080;
export const DEG = Math.PI / 180;

export function pal(ctx) {
  return {
    paper: ctx.color('bg'),
    ink: ctx.color('fg'),
    yellow: ctx.color('accent'),
    rust: ctx.color('panel'),
    grey: ctx.color('muted'),
    mortar: ctx.color('grid'),
  };
}

/** Deterministic LCG. render(t) is a pure function, so nothing here may use Math.random. */
export function mk(seed = 1) {
  let s = seed | 0 || 1;
  return () => {
    s = (s * 1664525 + 1013904223) | 0;
    return ((s >>> 8) & 0xffffff) / 0x1000000;
  };
}

export const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
export const smooth = (v) => {
  const x = clamp01(v);
  return x * x * (3 - 2 * x);
};
export const easeOut = (v) => 1 - (1 - clamp01(v)) ** 2.2;
export const lerp = (a, b, t) => a + (b - a) * t;

const FIBRE_DARK = 'rgba(112,98,72,0.055)';
const FIBRE_LIGHT = 'rgba(255,250,235,0.05)';
const INK_PIT = 'rgba(232,224,203,0.07)';

/** 纸：米色底 + 5200 根纤维 + 落墨点。一次画好，之后只贴。 */
export function paper(g, w, h, P, seed = 7) {
  g.fillStyle = P.paper;
  g.fillRect(0, 0, w, h);
  const r = mk(seed);
  g.lineCap = 'round';
  for (let i = 0; i < 5200; i++) {
    const x = r() * w;
    const y = r() * h;
    const a = (r() - 0.5) * 0.9 + (r() < 0.5 ? 0.35 : -0.35);
    const len = 5 + r() * 24;
    g.strokeStyle = r() < 0.55 ? FIBRE_DARK : FIBRE_LIGHT;
    g.lineWidth = 0.8 + r() * 0.9;
    g.beginPath();
    g.moveTo(x, y);
    g.lineTo(x + Math.cos(a) * len, y + Math.sin(a) * len);
    g.stroke();
  }
  for (let i = 0; i < 900; i++) {
    g.fillStyle = r() < 0.6 ? FIBRE_DARK : FIBRE_LIGHT;
    g.beginPath();
    g.arc(r() * w, r() * h, 0.6 + r() * 1.3, 0, Math.PI * 2);
    g.fill();
  }
}

/** 一整块墨上再落一层纸点点：油墨没吃满的地方，只在底图上用一次。 */
export function grain(g, w, h, seed = 3) {
  const r = mk(seed);
  g.globalAlpha = 0.8;
  g.fillStyle = INK_PIT;
  for (let i = 0; i < 1700; i++) {
    g.beginPath();
    g.arc(r() * w, r() * h, 0.5 + r() * 1.4, 0, Math.PI * 2);
    g.fill();
  }
}

/** 点阵：给"光"用。预生成一张，render 里裁切着贴。 */
export function dotField(w, h, gap, radius, color, seed = 5) {
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  const g = c.getContext('2d');
  const r = mk(seed);
  g.fillStyle = color;
  for (let y = gap * 0.5; y < h; y += gap) {
    for (let x = gap * 0.5; x < w; x += gap) {
      const rr = radius * (0.72 + r() * 0.5);
      g.beginPath();
      g.arc(x + (r() - 0.5) * 2, y + (r() - 0.5) * 2, rr, 0, Math.PI * 2);
      g.fill();
    }
  }
  return c;
}

/** 沿多边形边界重采样并抖动：木刻的边没有一条是直的。 */
export function roughen(pts, step, amp, rand) {
  const out = [];
  for (let i = 0; i < pts.length; i++) {
    const a = pts[i];
    const b = pts[(i + 1) % pts.length];
    const d = Math.hypot(b[0] - a[0], b[1] - a[1]);
    const k = Math.max(1, Math.round(d / step));
    for (let j = 0; j < k; j++) {
      const t = j / k;
      out.push([a[0] + (b[0] - a[0]) * t + (rand() - 0.5) * amp, a[1] + (b[1] - a[1]) * t + (rand() - 0.5) * amp]);
    }
  }
  return out;
}

export function poly(g, pts) {
  g.beginPath();
  pts.forEach(([x, y], i) => (i ? g.lineTo(x, y) : g.moveTo(x, y)));
  g.closePath();
}

/**
 * 一块墨。fill 后沿轮廓刻一道纸色沟（carve）——这就是版画里"线"的来源。
 */
export function mass(g, pts, P, { amp = 2.4, step = 26, carve = 3.6, seed = 1, fill = 'ink', alpha = 1, edge = null, edgeW = 2.4 } = {}) {
  const r = mk(seed);
  const p = roughen(pts, step, amp, r);
  g.save();
  g.globalAlpha = alpha;
  poly(g, p);
  g.fillStyle = P[fill];
  g.fill();
  if (carve > 0) {
    g.strokeStyle = P.paper;
    g.lineWidth = carve;
    g.lineJoin = 'round';
    g.stroke();
  }
  if (edge) {
    g.strokeStyle = edge;
    g.lineWidth = edgeW;
    g.lineJoin = 'round';
    g.stroke();
  }
  g.restore();
}

/** 平行排线（刀痕）。clip 传一个多边形，线只留在里面。 */
export function hatch(g, { x, y, w, h, gap = 10, angle = 42, width = 2, color, alpha = 1, clip = null, dash = 0 }) {
  g.save();
  if (clip) {
    poly(g, clip);
    g.clip();
  }
  g.translate(x + w / 2, y + h / 2);
  g.rotate(angle * DEG);
  const R = Math.hypot(w, h) / 2 + 2;
  g.beginPath();
  for (let d = -R; d <= R; d += gap) {
    const s = dash ? (d / gap) % 2 : 0;
    if (dash && Math.abs((d / gap) % 2) > 1) continue;
    g.moveTo(d, -R + s * 6);
    g.lineTo(d, R);
  }
  g.strokeStyle = color;
  g.globalAlpha = alpha;
  g.lineWidth = width;
  g.stroke();
  g.restore();
}

/**
 * 风：一笔粗的。压在白处用墨，压在黑处用纸 —— 不是"白边黑芯"那种细线，
 * 那种线在版画里读成划痕，读不出风。
 * pts 是中心线；width 为笔宽；dark 决定这一笔是墨还是纸。
 */
export function windStroke(g, P, { pts, width = 12, dark = true, alpha = 0.95, head = 0 }) {
  if (pts.length < 2) return;
  const left = [];
  const right = [];
  for (let i = 0; i < pts.length; i++) {
    const s = i / (pts.length - 1);
    // 笔锋：起笔细、走笔粗、收笔尖
    const w = width * (0.18 + 0.82 * Math.sin(Math.PI * Math.min(1, s * 1.06)) ** 0.55) * (1 - head * (1 - s) * 0.5);
    const a = pts[Math.max(0, i - 1)];
    const b = pts[Math.min(pts.length - 1, i + 1)];
    const dx = b[0] - a[0];
    const dy = b[1] - a[1];
    const l = Math.hypot(dx, dy) || 1;
    left.push([pts[i][0] - (dy / l) * w, pts[i][1] + (dx / l) * w]);
    right.push([pts[i][0] + (dy / l) * w, pts[i][1] - (dx / l) * w]);
  }
  const body = [...left, ...right.reverse()];
  g.save();
  g.globalAlpha = alpha;
  poly(g, body);
  g.fillStyle = dark ? P.ink : P.paper;
  g.fill();
  g.restore();
}

/** 一笔风折成 pts：从 (x,y) 向右上走，末端翘起来。 */
export function windPath(x, y, len, drop, lift, n = 10) {
  const pts = [];
  for (let i = 0; i <= n; i++) {
    const s = i / n;
    pts.push([x + len * s, y + drop * s + lift * s * s]);
  }
  return pts;
}

/** 一条布：中心线走 angle、法向按正弦摆，宽度两端收尖。 */
export function ribbon(g, { x, y, len, angle, w0, w1, waves = 1.6, amp = 14, phase = 0, color, edge, seed = 9, taper = 0.35 }) {
  const n = 16;
  const pts = [];
  const nx = Math.cos(angle + Math.PI / 2);
  const ny = Math.sin(angle + Math.PI / 2);
  for (let i = 0; i <= n; i++) {
    const s = i / n;
    const off = Math.sin(s * waves * Math.PI * 2 + phase) * amp * s ** 0.75;
    pts.push([x + Math.cos(angle) * len * s + nx * off, y + Math.sin(angle) * len * s + ny * off]);
  }
  const left = [];
  const right = [];
  for (let i = 0; i <= n; i++) {
    const s = i / n;
    const w = lerp(w0, w1, s) * Math.min(1, s * 7 + 0.15) * Math.min(1, (1 - s) * (1 / taper) + 0.1);
    const a = pts[Math.max(0, i - 1)];
    const b = pts[Math.min(n, i + 1)];
    const dx = b[0] - a[0];
    const dy = b[1] - a[1];
    const l = Math.hypot(dx, dy) || 1;
    left.push([pts[i][0] - (dy / l) * w, pts[i][1] + (dx / l) * w]);
    right.push([pts[i][0] + (dy / l) * w, pts[i][1] - (dx / l) * w]);
  }
  const body = [...left, ...right.reverse()];
  const r = mk(seed);
  const carved = roughen(body, 15, 1.7, r);
  g.save();
  // 套色错位：锈红版整体偏 (+3,−2)，墨线还在原位 —— 错开的地方露纸。
  g.translate(3, -2);
  poly(g, carved);
  g.fillStyle = color;
  g.fill();
  g.restore();
  if (edge) {
    poly(g, carved);
    g.strokeStyle = edge;
    g.lineWidth = 2.2;
    g.lineJoin = 'round';
    g.stroke();
  }
}

/** 背影男人：后脑、肩、大衣、围巾、腿、靴。没有脸，没有转身。 */
export function figureBack(g, P, { x, footY, h, flap = 0, lean = 0, seed = 21, scarfAngle = 84, scarfLen = 0.42, scarfPhase = 0, scarfAmp = 10, scarfW = 9, scarfSide = 1 }) {
  const u = (v) => v * h;
  const p = (px, py) => [x + u(px) + lean * u(-py - 0.6), footY + u(py)];

  // 腿：两条收尖的柱，靴子压在最下面
  for (const s of [-1, 1]) {
    const a = 0.062 * s;
    mass(g, [p(a - 0.043, -0.39), p(a + 0.043, -0.39), p(a + 0.05, -0.03), p(a - 0.05, -0.03)], P, {
      amp: 1.6, step: 22, carve: 2, seed: seed + s,
    });
    mass(g, [p(a - 0.056, -0.035), p(a + 0.062, -0.035), p(a + 0.075, 0.0), p(a - 0.07, 0.0)], P, {
      amp: 1.4, step: 18, carve: 0, seed: seed + 7 + s,
    });
  }

  // 大衣：肩 → 下摆（下摆被风顶起来 → flap）
  const coat = [
    p(-0.128, -0.795), p(-0.104, -0.862), p(0, -0.884), p(0.104, -0.862), p(0.128, -0.795),
    p(0.138, -0.7), p(0.163 + flap, -0.43), p(0.158 + flap * 0.8, -0.383),
    p(0.05, -0.372), p(-0.05, -0.372), p(-0.158, -0.383), p(-0.163, -0.43), p(-0.138, -0.7),
  ];
  mass(g, coat, P, { amp: 2.4, step: 24, carve: 3.4, seed: seed + 1 });

  // 大衣里刻几道沟：脊线、肩胛、下摆的褶
  g.save();
  g.strokeStyle = P.paper;
  g.lineWidth = 2.6;
  g.lineCap = 'round';
  for (const [x0, y0, x1, y1, x2, y2] of [
    [-0.09, -0.78, -0.11, -0.68, -0.12, -0.6],
    [0.09, -0.78, 0.112, -0.68, 0.118, -0.6],
    [-0.07, -0.44, -0.05, -0.47, -0.03, -0.5],
  ]) {
    g.beginPath();
    g.moveTo(...p(x0, y0));
    g.quadraticCurveTo(...p(x1, y1), ...p(x2, y2));
    g.stroke();
  }
  g.restore();

  // 后脑：一块墨，顶上刻出帽子的一道弧
  mass(g, [
    p(-0.072, -0.9), p(-0.062, -0.962), p(0, -0.982), p(0.062, -0.962), p(0.072, -0.9),
    p(0.06, -0.845), p(0, -0.828), p(-0.06, -0.845),
  ], P, { amp: 1.8, step: 16, carve: 2.6, seed: seed + 2 });
  g.save();
  g.strokeStyle = P.paper;
  g.lineWidth = 3;
  g.beginPath();
  g.moveTo(...p(-0.066, -0.925));
  g.quadraticCurveTo(...p(0, -0.947), ...p(0.066, -0.925));
  g.stroke();
  g.restore();

  // 围巾：一圈锈红压在肩上（错位套色），尾巴从左边甩出去
  const knot = p(0.105 * scarfSide, -0.843);
  if (scarfLen > 0) {
    ribbon(g, {
      x: knot[0], y: knot[1], len: u(scarfLen), angle: scarfAngle * DEG,
      w0: scarfW, w1: scarfW * 0.62, waves: 1.7, amp: scarfAmp, phase: scarfPhase,
      color: P.rust, edge: P.ink, seed: seed + 4,
    });
  }
  ribbon(g, {
    x: x - u(0.112), y: footY - u(0.858), len: u(0.232), angle: -1.5 * DEG,
    w0: 7.5, w1: 6.5, waves: 0.3, amp: 1.6, phase: 0, color: P.rust, edge: P.ink, seed: seed + 5, taper: 0.45,
  });
}

/** 站台吊牌：一块墨板，纸色的数字由 drawText 画上去（不画字，只画板）。 */
export function plate(g, P, { x, y, w, h, skew = 0, seed = 31 }) {
  mass(g, [[x, y + skew], [x + w, y], [x + w, y + h], [x, y + h + skew]], P, { amp: 1.6, step: 20, carve: 3, seed });
  // 板上一道刻沟，像框
  g.save();
  g.strokeStyle = P.paper;
  g.lineWidth = 1.6;
  g.globalAlpha = 0.75;
  g.strokeRect(x + 7, y + 7 + skew * 0.6, w - 14, h - 14);
  g.restore();
}

scenes.platform.mjs:
// 镜头一：站台（0–3.4s）
//
// 机位在对面站台，隔着轨道看过去。一条横向的带子结构：
//   上：天花板（墨）→ 墙（纸，瓷砖 + 线路图 + 吊牌）→ 站台地面 → 黄线 → 轨道坑（墨，前景）
// 左端所有横线都向地平线收（k=0.60），所以左深右浅；隧道口在最左边，是一个大黑拱。
// 动作只有一件：风从隧道那侧先到 —— 纸杯先滚、报纸先翻、围巾尾先抬。
// 静的东西在 mount() 里一次刻成，render 只画会动的三样 + 风痕 + 灰。

import { W, H, DEG, pal, mk, paper, grain, mass, hatch, poly, windStroke, windPath, figureBack, plate, clamp01, smooth, lerp } from './_print.mjs';

export const id = 'platform';
export const slots = { platform: { default: '3', role: 'label', maxChars: 3 } };

const HOR = 545; // 地平线（相机高度）
const K = 0.6; // 左端相对右端的收缩
const yL = (y) => HOR + (y - HOR) * K;
const lineY = (yR, x) => yR + (yL(yR) - yR) * (1 - x / W);

const CEIL = 96; // 天花板下沿（右端）
const BASE = 758; // 墙脚（右端）
const EDGE = 906; // 站台边（黄线外沿，右端）

let ctx;
let P;
let base = null;
let motes = [];
let gustSeed = [];
let lamps = [];

export function mount(context) {
  ctx = context;
  P = pal(ctx);
  const r = mk(913);
  motes = [];
  for (let i = 0; i < 26; i++) {
    motes.push({ x: 280 + r() * 1600, y: 260 + r() * 800, s: 0.9 + r() * 2.4, v: 60 + r() * 210, a: 0.1 + r() * 0.22 });
  }
  gustSeed = [];
  const bands = [330, 420, 512, 610, 742, 806, 884, 962, 1032];
  for (let i = 0; i < 16; i++) {
    const y = bands[i % bands.length] + (r() - 0.5) * 34;
    gustSeed.push({
      y,
      off: r(),
      birth: 0.55 + r() * 2.1,
      len: 210 + r() * 340,
      drop: (r() - 0.5) * 54,
      lift: -26 - r() * 62,
      w: 4.5 + r() * 5,
      dy: (r() - 0.5) * 40,
    });
  }
  lamps = [
    { c: 1650, w: 230 },
    { c: 1250, w: 200 },
    { c: 880, w: 176 },
    { c: 560, w: 152 },
    { c: 285, w: 130 },
  ];
  base = ctx.still(drawBase, { scale: 1 });
}

function isCream(x, y) {
  const xx = Math.max(0, Math.min(W, x));
  if (x < 330 && y > 292) return false; // 隧道口里
  if (y > lineY(EDGE + 8, xx)) return false; // 轨道坑
  if (y < lineY(CEIL, xx) + 2) return false; // 天花板
  return true;
}

function drawBase(g) {
  paper(g, W, H, P, 71);

  // ---- 天花板：一整块墨，灯管是刻掉的纸 -----------------------------
  mass(g, [
    [-8, -8], [W + 8, -8], [W + 8, CEIL + 2], [0, yL(CEIL)],
  ], P, { amp: 2.6, step: 30, carve: 4.5, seed: 101 });
  for (const { c, w } of lamps) {
    const y = lineY(CEIL, c) + 30 * (0.55 + 0.45 * (c / W));
    const th = 9 + 10 * (c / W);
    g.globalAlpha = 0.9;
    g.fillStyle = P.paper;
    g.fillRect(c - w / 2, y, w, th);
    g.globalAlpha = 0.55;
    g.fillStyle = P.yellow;
    g.fillRect(c - w / 2 + 8, y + th * 0.3, w - 16, th * 0.34);
    g.globalAlpha = 0.5;
    g.strokeStyle = P.ink;
    g.lineWidth = 2;
    g.beginPath();
    g.moveTo(c - w * 0.3, y);
    g.lineTo(c - w * 0.3, lineY(CEIL, c));
    g.moveTo(c + w * 0.3, y);
    g.lineTo(c + w * 0.3, lineY(CEIL, c));
    g.stroke();
    g.globalAlpha = 1;
  }

  // ---- 墙：瓷砖（横缝与竖缝都向左边收） -----------------------------
  g.strokeStyle = P.mortar;
  g.lineWidth = 2;
  g.globalAlpha = 0.6;
  for (let yR = CEIL + 92; yR < BASE - 24; yR += 84) {
    g.beginPath();
    g.moveTo(W, yR);
    g.lineTo(0, yL(yR));
    g.stroke();
  }
  for (let i = 0; i < 11; i++) {
    const x = W - 168 * i - 4.2 * i * i;
    if (x < -40) break;
    g.beginPath();
    g.moveTo(x, lineY(CEIL, x));
    g.lineTo(x, lineY(BASE, x));
    g.stroke();
  }
  g.globalAlpha = 1;

  // ---- 墙上的线路图：锈红版，纸色刻线 -------------------------------
  const poster = (x0, x1, f0, f1) => {
    const top = (x) => lineY(CEIL, x) + (lineY(BASE, x) - lineY(CEIL, x)) * f0;
    const bot = (x) => lineY(CEIL, x) + (lineY(BASE, x) - lineY(CEIL, x)) * f1;
    return [[x0, top(x0)], [x1, top(x1)], [x1, bot(x1)], [x0, bot(x0)]];
  };
  const map = poster(360, 690, 0.2, 0.82);
  mass(g, map, P, { amp: 1.8, step: 22, carve: 3, seed: 111, fill: 'rust' });
  g.save();
  poly(g, map);
  g.clip();
  g.strokeStyle = P.paper;
  g.lineWidth = 3.2;
  g.globalAlpha = 0.95;
  g.beginPath();
  g.moveTo(392, 430);
  g.lineTo(500, 396);
  g.lineTo(668, 372);
  g.stroke();
  g.beginPath();
  g.moveTo(392, 470);
  g.lineTo(520, 446);
  g.lineTo(668, 438);
  g.stroke();
  g.fillStyle = P.paper;
  for (const [x, y, r0] of [[420, 422, 5], [500, 396, 6], [592, 380, 5], [668, 372, 5], [452, 460, 4], [592, 442, 4], [668, 438, 4]]) {
    g.beginPath();
    g.arc(x, y, r0, 0, Math.PI * 2);
    g.fill();
  }
  g.restore();

  // 海报一角被风掀起：一块纸色三角（静态，用来暗示上一阵风）
  g.save();
  g.fillStyle = P.paper;
  g.strokeStyle = P.ink;
  g.lineWidth = 2;
  g.beginPath();
  g.moveTo(690, 404);
  g.lineTo(690, 468);
  g.lineTo(636, 486);
  g.closePath();
  g.fill();
  g.stroke();
  g.restore();

  // ---- 吊牌：从天花板吊下来的一块墨板 ---------------------------------
  const px = 1006;
  const py = lineY(CEIL, px) + 46;
  g.strokeStyle = P.ink;
  g.lineWidth = 3;
  g.beginPath();
  g.moveTo(px + 26, py);
  g.lineTo(px + 26, lineY(CEIL, px + 26));
  g.moveTo(px + 158, py);
  g.lineTo(px + 158, lineY(CEIL, px + 158));
  g.stroke();
  plate(g, P, { x: px, y: py, w: 184, h: 96, skew: 5, seed: 115 });

  // ---- 站台地面：向左边收的一小条 ------------------------------------
  const plat = [[W + 4, BASE], [W + 4, EDGE + 6], [-4, yL(EDGE + 6)], [-4, yL(BASE)]];
  g.save();
  poly(g, plat);
  g.clip();
  g.strokeStyle = P.mortar;
  g.globalAlpha = 0.42;
  g.lineWidth = 1.8;
  for (let x = 120; x < W; x += 210) {
    g.beginPath();
    g.moveTo(x, lineY(BASE, x));
    g.lineTo(x - 60, lineY(EDGE + 6, x - 60));
    g.stroke();
  }
  hatch(g, { x: 0, y: 700, w: W, h: 220, gap: 46, angle: 42, width: 1.4, color: P.mortar, alpha: 0.22, clip: plat });
  g.restore();

  // ---- 黄线 ----------------------------------------------------------
  mass(g, [[W + 4, EDGE], [W + 4, EDGE + 26], [-4, yL(EDGE + 26)], [-4, yL(EDGE)]], P, {
    amp: 1.6, step: 24, carve: 2.4, seed: 121, fill: 'yellow',
  });

  // ---- 轨道坑：前景的黑 ----------------------------------------------
  const pit = [[W + 4, EDGE + 24], [W + 4, H + 8], [-8, H + 8], [-8, yL(EDGE + 24)]];
  mass(g, pit, P, { amp: 2.4, step: 26, carve: 3.4, seed: 123 });
  g.save();
  poly(g, pit);
  g.clip();
  // 钢轨：两条纸色线，跟着地面一起收
  for (const yR of [1010, 1054]) {
    g.strokeStyle = P.paper;
    g.globalAlpha = 0.72;
    g.lineWidth = 2.6;
    g.beginPath();
    g.moveTo(W + 4, yR);
    g.lineTo(-8, yL(yR));
    g.stroke();
  }
  // 枕木
  g.globalAlpha = 0.2;
  g.lineWidth = 9;
  for (let x = W; x > -60; x -= 82) {
    const t = 1 - x / W;
    const y0 = lineY(EDGE + 26, x);
    g.beginPath();
    g.moveTo(x, y0 + 8 + t * 2);
    g.lineTo(x - 12, y0 + 62);
    g.stroke();
  }
  g.restore();

  // ---- 隧道口：最左边的大黑拱 ----------------------------------------
  const tunnel = () => {
    g.beginPath();
    g.moveTo(-90, 1040);
    g.lineTo(-90, 470);
    g.quadraticCurveTo(-90, 300, 118, 300);
    g.quadraticCurveTo(322, 300, 322, 470);
    g.lineTo(322, 1040);
    g.closePath();
  };
  g.save();
  tunnel();
  g.fillStyle = P.ink;
  g.fill();
  g.strokeStyle = P.paper;
  g.lineWidth = 7;
  g.stroke();
  g.restore();
  // 洞里：一条更黑的底、一盏锈红信号灯
  g.save();
  tunnel();
  g.clip();
  g.fillStyle = P.ink;
  g.fillRect(-90, 300, 420, 760);
  g.globalAlpha = 0.8;
  g.strokeStyle = P.paper;
  g.lineWidth = 2;
  for (let i = 0; i < 5; i++) {
    g.beginPath();
    g.moveTo(180 + i * 22, 330);
    g.lineTo(180 + i * 22, 1040);
    g.globalAlpha = 0.05 + i * 0.02;
    g.stroke();
  }
  g.globalAlpha = 1;
  g.fillStyle = P.rust;
  g.beginPath();
  g.arc(196, 604, 7, 0, Math.PI * 2);
  g.fill();
  g.fillStyle = P.paper;
  g.globalAlpha = 0.5;
  g.beginPath();
  g.arc(196, 604, 15, 0, Math.PI * 2);
  g.lineWidth = 2;
  g.strokeStyle = P.paper;
  g.stroke();
  g.restore();

  // ---- 长椅（靠墙，右半边） -------------------------------------------
  const bench = [[1430, 800], [1740, 790], [1740, 816], [1430, 828]];
  mass(g, bench, P, { amp: 1.4, step: 20, carve: 2.4, seed: 131 });
  mass(g, [[1430, 766], [1740, 758], [1740, 768], [1430, 778]], P, { amp: 1.1, step: 18, carve: 0, seed: 133 });
  g.save();
  g.strokeStyle = P.ink;
  g.lineWidth = 6;
  for (const bx of [1446, 1718]) {
    g.beginPath();
    g.moveTo(bx, 806);
    g.lineTo(bx + 2, 862);
    g.stroke();
  }
  g.restore();

  // ---- 人落在地上的淡墨（人本身在 render 里画） ------------------------
  g.save();
  g.globalAlpha = 0.15;
  g.fillStyle = P.ink;
  g.beginPath();
  g.ellipse(1216, 846, 118, 17, 0, 0, Math.PI * 2);
  g.fill();
  g.restore();

  grain(g, W, H, 77);
}

// ---------------------------------------------------------------- render

function drawCup(g, x, y, rot, sc) {
  g.save();
  g.translate(x, y);
  g.rotate(rot);
  g.scale(sc, sc);
  mass(g, [[-18, -28], [18, -28], [12, 28], [-12, 28]], P, { amp: 0.9, step: 12, carve: 0, seed: 201, fill: 'paper', edge: P.ink, edgeW: 2.6 });
  g.strokeStyle = P.ink;
  g.lineWidth = 3.2;
  g.beginPath();
  g.moveTo(-18, -28);
  g.quadraticCurveTo(0, -22, 18, -28);
  g.stroke();
  g.save();
  g.beginPath();
  g.rect(-19, -8, 38, 26);
  g.clip();
  hatch(g, { x: -19, y: -8, w: 38, h: 26, gap: 5, angle: 42, width: 1.5, color: P.ink, alpha: 0.7 });
  g.restore();
  g.restore();
}

function drawPaper(g, cx, cy, u, rot, sc) {
  const w = 126 * sc;
  const h = 82 * sc;
  const lift = u;
  const pts = [
    [cx - w / 2, cy - h / 2 - lift * 30],
    [cx + w / 2, cy - h / 2 - lift * 54],
    [cx + w / 2 - lift * 18, cy + h / 2 - lift * 12],
    [cx - w / 2 + lift * 12, cy + h / 2],
  ];
  g.save();
  g.translate(cx, cy);
  g.rotate(rot);
  g.translate(-cx, -cy);
  mass(g, pts, P, { amp: 1.4, step: 16, carve: 0, seed: 205, fill: 'paper', edge: P.ink, edgeW: 2.6 });
  g.strokeStyle = P.ink;
  g.globalAlpha = 0.8;
  g.lineWidth = 1.7;
  for (let i = 0; i < 4; i++) {
    const yy = cy - h / 2 + 15 + i * 15;
    g.beginPath();
    g.moveTo(cx - w / 2 + 14, yy);
    g.lineTo(cx + w / 2 - 22 - i * 7, yy - 2);
    g.stroke();
  }
  g.globalAlpha = 1;
  g.restore();
}

const easeOut = (v) => 1 - (1 - clamp01(v)) ** 2;

export function render(t) {
  const g = ctx.canvas.getContext('2d');
  g.clearRect(0, 0, W, H);
  g.drawImage(base, 0, 0, W, H);

  // 吊牌上的数字（全片唯一一处字）
  ctx.drawText('platform', {
    x: 1016, y: lineY(CEIL, 1006) + 68, w: 164, size: 62, weight: 700, family: 'mono', align: 'center',
    color: P.paper, lineHeight: 1, letterSpacing: 6,
  });

  // 报纸：1.5s 起一角翻，2.3s 起离地往右飘
  const pu = clamp01((t - 1.5) / 1.5);
  const pfly = clamp01((t - 2.3) / 1.1);
  const px = 892 + pfly * 300;
  drawPaper(g, px, lineY(EDGE + 4, px) - 42 - smooth(pu) * 40 - easeOut(pfly) * 170, pu, pfly * 0.55, 1 + pfly * 0.1);

  // 纸杯：1.0s 起被推着滚，越滚越快
  const cu = clamp01((t - 1.0) / 2.3);
  const cx = 470 + 1130 * cu ** 1.5;
  const bob = -Math.abs(Math.sin(cu * 15)) * 5 * cu;
  drawCup(g, cx, lineY(EDGE + 4, cx) - 32 + bob, cu * 7.6, 0.95 + cu * 0.22);

  // 人：围巾 1.3s 起抬，大衣下摆 2.0s 起鼓
  const lift = smooth((t - 1.3) / 1.9);
  figureBack(g, P, {
    x: 1210, footY: 840, h: 448,
    scarfAngle: lerp(84, -4, lift),
    scarfLen: lerp(0.28, 0.42, lift),
    scarfPhase: t * 5.4,
    scarfAmp: lerp(3, 17, lift),
    flap: 0.013 * smooth((t - 2.0) / 1.2),
    scarfSide: 1,
    seed: 41,
  });

  // 风：从隧道那边推过来的粗刻痕。压在白处用墨、压在黑处用纸。
  // 每一笔有自己的"起风时刻"，所以风是逐渐到的，不是一开始就满屏。
  for (let i = 0; i < gustSeed.length; i++) {
    const s = gustSeed[i];
    const age = t - s.birth;
    if (age < 0) continue;
    const gate = clamp01(age / 0.45);
    const ph = (age * 0.5 + s.off * 0.55) % 1.35;
    const x = 90 + ph * 1900;
    const y = s.y + ph * s.dy + Math.sin(ph * 2.4 + i * 1.7) * 11;
    const len = s.len * (0.62 + ph * 0.8);
    const pts = windPath(x, y, len, s.drop, s.lift * (0.55 + ph * 0.8));
    const dark = isCream(x + len * 0.45, y + 6);
    windStroke(g, P, { pts, width: s.w * (0.6 + ph * 0.55), dark, alpha: 0.92 * gate });
  }

  // 灰：始终有一点在飘
  for (const m of motes) {
    const x = ((m.x + m.v * t) % (W + 220)) - 110;
    const y = m.y + Math.sin(t * 1.6 + m.x) * 7;
    g.globalAlpha = m.a;
    g.fillStyle = P.ink;
    g.beginPath();
    g.ellipse(x, y, m.s * 2.6, m.s * 0.95, 0.25, 0, Math.PI * 2);
    g.fill();
  }
  g.globalAlpha = 1;
}

scenes.train.mjs:
// 镜头三：车来了（7.2–11.0s）
//
// 机位在站台上，正对车侧。物：一整面车厢（车窗、车门缝、锈红腰带）、黄线、一个背影。
// 动作：车体由左向右扫过、减速、停稳；门缝亮开一线；围巾从横飞落回肩上。
// 画法：车厢在 mount() 里刻成一节（1400×820 的版），render 只平移贴；速度靠横的刻痕带，
//       不靠模糊——版画没有模糊。

import { W, H, DEG, pal, mk, paper, grain, mass, hatch, poly, windStroke, windPath, figureBack, clamp01, smooth, lerp } from './_print.mjs';

export const id = 'train';

const CAR = 1400; // 一节车
const TRAIN_H = 820; // 车体高度（站在地板上沿）
const BASE_Y = 820; // 车体下沿 / 站台边
const YEL = 872; // 黄线中心

let ctx;
let P;
let base = null;
let car = null;
let carPaper = null;
let gusts = [];
let scraps = [];

export function mount(context) {
  ctx = context;
  P = pal(ctx);
  car = makeCar(2);
  gusts = [];
  const r = mk(733);
  for (let i = 0; i < 12; i++) {
    gusts.push({ y: 90 + r() * 900, off: r(), len: 220 + r() * 420, lift: -22 - r() * 54, w: 4.5 + r() * 6, v: 0.5 + r() * 0.7 });
  }
  scraps = [];
  for (let i = 0; i < 7; i++) {
    scraps.push({ y: 240 + r() * 640, s: 0.6 + r() * 1.1, off: r(), rot: r() * 6.28, spin: (r() - 0.5) * 10, v: 0.6 + r() * 0.8 });
  }
  base = ctx.still(drawBase, { scale: 1 });
}

/** 一节车厢，刻进一张 2 倍大的版里。 */
function makeCar(scale) {
  const c = document.createElement('canvas');
  c.width = CAR * scale;
  c.height = TRAIN_H * scale;
  const g = c.getContext('2d');
  g.scale(scale, scale);
  drawCar(g);
  return c;
}

function drawCar(g) {
  // 车身：一整块墨
  mass(g, [[-10, -10], [CAR + 10, -10], [CAR + 10, TRAIN_H + 10], [-10, TRAIN_H + 10]], P, { amp: 1.6, step: 40, carve: 0, seed: 601 });
  // 车顶的一道纸线
  g.strokeStyle = P.paper;
  g.globalAlpha = 0.55;
  g.lineWidth = 4;
  g.beginPath();
  g.moveTo(0, 14);
  g.lineTo(CAR, 14);
  g.stroke();
  g.globalAlpha = 1;

  // 车身排线：斜的，越靠下越密
  hatch(g, { x: 0, y: 600, w: CAR, h: 220, gap: 7, angle: 42, width: 2, color: P.paper, alpha: 0.1 });

  // 车窗：纸白的四个洞
  for (let i = 0; i < 4; i++) {
    const x = 78 + i * 236;
    mass(g, [[x, 196], [x + 190, 196], [x + 190, 592], [x, 592]], P, {
      amp: 1.4, step: 22, carve: 0, seed: 610 + i, fill: 'paper', edge: P.ink, edgeW: 3,
    });
    // 窗里的一点"车厢内"：上部一道横线，下部一块暗
    g.strokeStyle = P.ink;
    g.globalAlpha = 0.35;
    g.lineWidth = 3;
    g.beginPath();
    g.moveTo(x + 6, 250);
    g.lineTo(x + 184, 250);
    g.stroke();
    g.globalAlpha = 0.18;
    g.fillStyle = P.ink;
    g.fillRect(x + 8, 470, 174, 116);
    g.globalAlpha = 1;
  }

  // 车门：两扇，中间一道缝
  mass(g, [[1050, 60], [1310, 60], [1310, 790], [1050, 790]], P, { amp: 1.6, step: 24, carve: 3.2, seed: 621 });
  // 门上的窗
  mass(g, [[1082, 196], [1278, 196], [1278, 500], [1082, 500]], P, {
    amp: 1.4, step: 22, carve: 0, seed: 623, fill: 'paper', edge: P.ink, edgeW: 3,
  });
  // 门的踏步（底部一块浅色）
  mass(g, [[1056, 700], [1304, 700], [1304, 790], [1056, 790]], P, {
    amp: 1.2, step: 18, carve: 0, seed: 625, fill: 'paper', edge: P.ink, edgeW: 2.4, alpha: 0.85,
  });

  // 锈红腰带：从车头一直拉过去，被人和窗切断也行
  mass(g, [[-10, 620], [CAR + 10, 620], [CAR + 10, 686], [-10, 686]], P, { amp: 1.4, step: 30, carve: 2.4, seed: 631, fill: 'rust' });

  // 车厢接缝：一道竖的纸线
  g.strokeStyle = P.paper;
  g.globalAlpha = 0.5;
  g.lineWidth = 3;
  g.beginPath();
  g.moveTo(4, 24);
  g.lineTo(4, TRAIN_H - 10);
  g.stroke();
  g.globalAlpha = 1;
}

function drawBase(g) {
  paper(g, W, H, P, 71);
  // 站台地面
  mass(g, [[-8, BASE_Y - 4], [W + 8, BASE_Y - 4], [W + 8, H + 8], [-8, H + 8]], P, {
    amp: 1.6, step: 30, carve: 0, seed: 641, fill: 'paper',
  });
  // 地面排线 / 砖缝
  g.save();
  g.beginPath();
  g.rect(-8, BASE_Y, W + 16, H);
  g.clip();
  g.strokeStyle = P.mortar;
  g.globalAlpha = 0.45;
  g.lineWidth = 1.8;
  for (let y = BASE_Y + 46; y < H; y += 54) {
    g.beginPath();
    g.moveTo(-8, y);
    g.lineTo(W + 8, y);
    g.stroke();
  }
  for (let x = 40; x < W; x += 132) {
    g.beginPath();
    g.moveTo(x, BASE_Y);
    g.lineTo(x - 40, H);
    g.stroke();
  }
  hatch(g, { x: -8, y: BASE_Y, w: W + 16, h: H - BASE_Y, gap: 26, angle: 42, width: 2.4, color: P.mortar, alpha: 0.3 });
  g.restore();

  // 黄线：贴墙根的一条
  mass(g, [[-8, YEL - 22], [W + 8, YEL - 22], [W + 8, YEL + 22], [-8, YEL + 22]], P, {
    amp: 1.6, step: 26, carve: 2.6, seed: 643, fill: 'yellow',
  });
  // 黄线底下的一道墨（站台边）
  mass(g, [[-8, YEL + 22], [W + 8, YEL + 22], [W + 8, YEL + 34], [-8, YEL + 34]], P, { amp: 1.2, step: 24, carve: 0, seed: 645 });

  grain(g, W, H, 79);
}

// ---------------------------------------------------------------- render

function isFloor(x, y) {
  return y > YEL + 30;
}

export function render(t) {
  const g = ctx.canvas.getContext('2d');
  g.clearRect(0, 0, W, H);
  g.drawImage(base, 0, 0, W, H);

  // 车体的位置：2.5s 到站，之后一次很轻的回弹
  // 走法：先匀速冲一段，后 40% 减速到停 —— 不然后半段等于静止
  const D = 2600;
  const T = 2.55;
  const u = clamp01(t / T);
  const f = u < 0.6 ? (0.72 * u) / 0.6 : 0.72 + 0.28 * (1 - (1 - (u - 0.6) / 0.4) ** 1.4);
  let off = -D * (1 - f);
  if (t > T) off += -16 * Math.sin((t - T) * 5.2) * Math.exp(-(t - T) * 3.2);
  const speed = u < 0.6 ? 1 : Math.max(0, 1 - (u - 0.6) / 0.4) ** 0.8;
  const stopped = clamp01((t - 2.65) / 0.5);

  // 车厢（贴三次，够铺满）
  g.save();
  g.translate(off, 0);
  for (let i = -1; i < 3; i++) g.drawImage(car, i * CAR, 0, CAR, TRAIN_H);
  // 速度痕：车快的时候，窗光拉成横条
  if (speed > 0.06) {
    g.save();
    g.globalAlpha = speed * 0.9;
    g.fillStyle = P.paper;
    for (let i = 0; i < 9; i++) {
      const y = 200 + i * 44;
      const len = 300 + ((i * 137) % 520);
      g.fillRect(((i * 311) % CAR) - 40, y, len, 7 + (i % 3) * 4);
    }
    g.restore();
  }
  g.restore();

  // 门缝：停稳之后亮开一线（纸色的光从缝里出来）
  const open = smooth((t - 2.5) / 0.8);
  if (open > 0) {
    const seamX = off + 1180;
    g.save();
    g.fillStyle = P.paper;
    g.globalAlpha = 0.95;
    g.fillRect(seamX - (2 + 12 * open), 70, 4 + 24 * open, TRAIN_H - 80);
    // 门缝漏到站台上的一块光
    g.globalAlpha = 0.75 * open;
    poly(g, [[seamX - 40, YEL + 26], [seamX + 44, YEL + 26], [seamX + 120, H], [seamX - 120, H]]);
    g.fill();
    g.restore();
  }

  // 影子
  g.save();
  g.globalAlpha = 0.22;
  g.fillStyle = P.ink;
  g.beginPath();
  g.ellipse(1216, 1014, 150, 24, 0, 0, Math.PI * 2);
  g.fill();
  g.restore();

  // 人：先贴一层纸色的剪影（错开 7px），再压墨 —— 黑车前面靠这道刀口立住
  const fall = smooth((t - 2.45) / 1.25);
  const fig = {
    x: 1212, footY: 1012, h: 566,
    scarfAngle: lerp(-9, 82, fall),
    scarfLen: lerp(0.42, 0.3, fall),
    scarfPhase: t * 6.2,
    scarfAmp: lerp(19, 3, fall),
    flap: 0.012 * (1 - fall),
    scarfSide: 1,
    seed: 41,
  };
  g.save();
  g.translate(-5, -2);
  figureBack(g, { ...P, ink: P.paper, rust: P.paper, yellow: P.paper, grey: P.paper, mortar: P.paper }, fig);
  g.restore();
  figureBack(g, P, fig);

  // 风：车停稳就断，最后只剩一两笔在飘
  const windAmp = t < 2.65 ? 1 : Math.max(0.12, 1 - (t - 2.65) / 1.1);
  for (let i = 0; i < gusts.length; i++) {
    const s = gusts[i];
    const ph = (t * 0.5 * s.v + s.off) % 1.2;
    const x = -140 + ph * 2140;
    const y = s.y + Math.sin(ph * 2.4 + i * 1.3) * 14;
    const pts = windPath(x, y, s.len * (0.6 + ph * 0.7), 16, s.lift * (0.5 + ph));
    const dark = isFloor(x + 150, y + 10);
    windStroke(g, P, { pts, width: s.w * (0.5 + ph * 0.6) * (0.5 + 0.5 * windAmp), dark, alpha: 0.9 * windAmp });
  }

  // 碎纸
  for (const d of scraps) {
    const age = t - 0.25;
    if (age < 0) continue;
    const ph = (age * 0.5 * d.v + d.off) % 1.2;
    const x = -120 + ph * 2180;
    const y = d.y + Math.sin(ph * 5 + d.rot) * 44 - ph * 120;
    const fade = clamp01(1.4 - age);
    g.save();
    g.globalAlpha = fade;
    g.translate(x, y);
    g.rotate(d.rot + ph * d.spin);
    g.scale(d.s, d.s);
    mass(g, [[-17, -12], [18, -14], [15, 12], [-16, 10]], P, { amp: 1, step: 10, carve: 0, seed: 651, fill: 'paper', edge: P.ink, edgeW: 2.2 });
    g.strokeStyle = P.ink;
    g.globalAlpha = fade * 0.7;
    g.lineWidth = 1.2;
    g.beginPath();
    g.moveTo(-9, -3);
    g.lineTo(8, -4);
    g.moveTo(-9, 3);
    g.lineTo(6, 2);
    g.stroke();
    g.restore();
  }
  g.globalAlpha = 1;
}

scenes.tunnel.mjs:
// 镜头二：隧道口（3.4–7.2s）
//
// 机位搬到轨道里，正对洞口。物：隧道拱、拱圈的锈红楔石、道床与两条钢轨、站台的一角。
// 动作：黑洞口里的车头灯从针尖涨满，把洞壁的肋一道一道点出来；
//       然后车头从灯的四周**长出来**——黑包着白，朝镜头压过来。
// 缓推 1.00→1.09。风在这镜里只剩痕和飞过的碎纸，人不在。

import { W, H, DEG, pal, mk, paper, grain, mass, hatch, poly, windStroke, windPath, plate, clamp01, smooth, lerp } from './_print.mjs';

export const id = 'tunnel';

const CX = 720; // 拱心
const SPRING = 700; // 拱脚线
const R_IN = 452; // 拱内半径
const LAMP = { x: 700, y: 790 }; // 车头灯（还在洞里，比道床高一点）

let ctx;
let P;
let base = null;
let debris = [];
let motes = [];
let wind = [];

export function mount(context) {
  ctx = context;
  P = pal(ctx);
  const r = mk(517);
  debris = [];
  for (let i = 0; i < 9; i++) {
    debris.push({ y: 300 + r() * 760, s: 0.5 + r() * 1.1, off: r(), rot: r() * 6.28, spin: (r() - 0.5) * 9, v: 0.55 + r() * 0.6 });
  }
  motes = [];
  for (let i = 0; i < 40; i++) {
    motes.push({ x: r() * W, y: 200 + r() * 880, s: 1 + r() * 2.6, v: 90 + r() * 260, a: 0.1 + r() * 0.3 });
  }
  wind = [];
  for (let i = 0; i < 12; i++) {
    wind.push({ y: 240 + r() * 800, off: r(), birth: 0.35 + r() * 3, len: 240 + r() * 420, lift: -20 - r() * 70, w: 4 + r() * 5 });
  }
  base = ctx.still(drawBase, { scale: 1 });
}

function arch(g) {
  g.beginPath();
  g.moveTo(CX - R_IN, H + 20);
  g.lineTo(CX - R_IN, SPRING);
  g.arc(CX, SPRING, R_IN, Math.PI, 0);
  g.lineTo(CX + R_IN, H + 20);
  g.closePath();
}

function drawBase(g) {
  paper(g, W, H, P, 71);

  // ---- 洞外的那面墙：瓷砖 -------------------------------------------
  g.strokeStyle = P.mortar;
  g.globalAlpha = 0.5;
  g.lineWidth = 2;
  for (let y = 210; y < H; y += 96) {
    g.beginPath();
    g.moveTo(0, y);
    g.lineTo(W, y);
    g.stroke();
  }
  for (let x = 40; x < W; x += 104) {
    g.beginPath();
    g.moveTo(x, 0);
    g.lineTo(x, H);
    g.stroke();
  }
  g.globalAlpha = 1;

  // ---- 天花：一条墨带压住顶 ------------------------------------------
  mass(g, [[-8, -8], [W + 8, -8], [W + 8, 132], [-8, 108]], P, { amp: 2.6, step: 30, carve: 4, seed: 301 });
  // 灯管
  for (const [x, w] of [[250, 210], [880, 230], [1520, 240]]) {
    g.fillStyle = P.paper;
    g.fillRect(x - w / 2, 156, w, 12);
    g.fillStyle = P.yellow;
    g.globalAlpha = 0.6;
    g.fillRect(x - w / 2 + 8, 159, w - 16, 5);
    g.globalAlpha = 1;
  }

  // ---- 拱圈：一圈锈红楔石 --------------------------------------------
  const ring = () => {
    g.beginPath();
    g.arc(CX, SPRING, R_IN + 54, Math.PI, 0);
    g.lineTo(CX + R_IN, SPRING);
    g.arc(CX, SPRING, R_IN, 0, Math.PI, true);
    g.closePath();
  };
  g.save();
  ring();
  g.fillStyle = P.rust;
  g.fill();
  g.strokeStyle = P.ink;
  g.lineWidth = 3;
  g.stroke();
  g.restore();
  // 楔石的缝：从拱心放射出去
  g.save();
  ring();
  g.clip();
  g.strokeStyle = P.paper;
  g.lineWidth = 2.4;
  g.globalAlpha = 0.85;
  for (let i = 0; i <= 26; i++) {
    const a = Math.PI + (i / 26) * Math.PI;
    g.beginPath();
    g.moveTo(CX + Math.cos(a) * (R_IN + 2), SPRING + Math.sin(a) * (R_IN + 2));
    g.lineTo(CX + Math.cos(a) * (R_IN + 56), SPRING + Math.sin(a) * (R_IN + 56));
    g.stroke();
  }
  g.restore();

  // ---- 洞口：黑 ------------------------------------------------------
  g.save();
  arch(g);
  g.fillStyle = P.ink;
  g.fill();
  g.strokeStyle = P.paper;
  g.lineWidth = 5;
  g.stroke();
  g.restore();

  // ---- 道床：枕木和两条钢轨，往洞里收 --------------------------------
  g.save();
  arch(g);
  g.clip();
  g.fillStyle = P.ink;
  g.fillRect(0, 0, W, H);
  // 洞壁的肋（只有被灯照到才看得见，render 里再画亮的）
  g.restore();

  // 洞外的道砟 + 枕木
  mass(g, [[-8, 1012], [W + 8, 992], [W + 8, H + 8], [-8, H + 8]], P, { amp: 2.2, step: 24, carve: 3, seed: 305 });
  // 钢轨：两根，从脚下一路收进洞里
  for (const side of [-1, 1]) {
    g.save();
    g.strokeStyle = P.paper;
    g.globalAlpha = 0.8;
    g.lineWidth = 4.4;
    g.beginPath();
    g.moveTo(LAMP.x + side * 560, H + 20);
    g.lineTo(LAMP.x + side * 30, LAMP.y + 26);
    g.stroke();
    g.restore();
  }
  g.save();
  g.beginPath();
  g.rect(-8, 990, W + 16, H);
  g.clip();
  g.strokeStyle = P.paper;
  g.globalAlpha = 0.22;
  g.lineWidth = 10;
  for (let i = 0; i < 9; i++) {
    const t = i / 8;
    const y = 1040 - t * 34;
    const x = 300 + t * 220;
    g.beginPath();
    g.moveTo(x, y);
    g.lineTo(x + 700 - t * 300, y - 20 + t * 18);
    g.stroke();
  }
  g.restore();

  // ---- 站台边（右下角的一小条，够认地方就行） ------------------------
  mass(g, [[1240, 986], [W + 8, 958], [W + 8, 1030], [1240, 1058]], P, { amp: 1.8, step: 22, carve: 2.4, seed: 307, fill: 'yellow' });
  mass(g, [[1240, 1056], [W + 8, 1028], [W + 8, H + 8], [1240, H + 8]], P, { amp: 2, step: 24, carve: 2.6, seed: 308 });
  g.save();
  g.strokeStyle = P.mortar;
  g.globalAlpha = 0.5;
  g.lineWidth = 2;
  for (let x = 1260; x < W; x += 92) {
    g.beginPath();
    g.moveTo(x, 760);
    g.lineTo(x, 980);
    g.stroke();
  }
  g.restore();

  // ---- 信号灯（洞里的锈红点） ----------------------------------------
  g.fillStyle = P.rust;
  g.beginPath();
  g.arc(268, 700, 8, 0, Math.PI * 2);
  g.fill();
  g.globalAlpha = 0.65;
  g.strokeStyle = P.paper;
  g.lineWidth = 2;
  g.beginPath();
  g.arc(268, 700, 17, 0, Math.PI * 2);
  g.stroke();
  g.globalAlpha = 1;

  grain(g, W, H, 78);
}

// ---------------------------------------------------------------- render

function isWall(x, y) {
  const dx = x - CX;
  const dy = y - SPRING;
  const r = Math.hypot(dx, dy);
  const inside = y > SPRING ? Math.abs(dx) < R_IN : r < R_IN;
  if (inside) return false;
  if (y > 1012) return false;
  if (y < 140) return false;
  return true;
}

function drawDebris(g, x, y, rot, s) {
  g.save();
  g.translate(x, y);
  g.rotate(rot);
  g.scale(s, s);
  mass(g, [[-16, -11], [17, -13], [14, 12], [-15, 9]], P, { amp: 1, step: 10, carve: 0, seed: 211, fill: 'paper', edge: P.ink, edgeW: 2.2 });
  g.strokeStyle = P.ink;
  g.globalAlpha = 0.7;
  g.lineWidth = 1.2;
  g.beginPath();
  g.moveTo(-9, -3);
  g.lineTo(8, -4);
  g.moveTo(-9, 3);
  g.lineTo(6, 2);
  g.stroke();
  g.restore();
}

export function render(t) {
  const g = ctx.canvas.getContext('2d');
  g.clearRect(0, 0, W, H);

  // 缓推
  const push = 1 + 0.088 * smooth(t / 3.8);
  g.save();
  g.translate(CX * 0.75, SPRING * 1.05);
  g.scale(push, push);
  g.translate(-CX * 0.75, -SPRING * 1.05);
  g.drawImage(base, 0, 0, W, H);

  const lit = smooth((t - 0.9) / 2.55);
  const R = 40 + 250 * lit ** 1.4;
  const RX = R * 1.42;
  const RY = R * 0.5;

  // ---- 洞里被点亮的部分（裁在拱里） ---------------------------------
  if (lit > 0) {
    g.save();
    arch(g);
    g.clip();
    g.save();
    g.beginPath();
    g.ellipse(LAMP.x, LAMP.y + 10, RX, RY, 0, 0, Math.PI * 2);
    g.clip();
    g.fillStyle = P.yellow;
    g.fillRect(0, 0, W, H);
    // 洞壁的肋：被灯一道道点出来
    g.strokeStyle = P.ink;
    g.lineWidth = 3;
    g.globalAlpha = 0.16;
    for (let i = 1; i <= 4; i++) {
      g.beginPath();
      g.arc(LAMP.x, LAMP.y, 210 + i * 168, 0, Math.PI * 2);
      g.stroke();
    }
    g.restore();
    g.restore();
  }

  // ---- 光沿着两条钢轨铺到脚下 ----------------------------------------
  if (lit > 0.02) {
    for (const side of [-1, 1]) {
      g.save();
      g.beginPath();
      g.moveTo(LAMP.x + side * 26, LAMP.y + 20);
      g.lineTo(LAMP.x + side * 560, H + 20);
      g.lineTo(LAMP.x + side * 640, H + 20);
      g.lineTo(LAMP.x + side * 58, LAMP.y + 20);
      g.closePath();
      g.fillStyle = P.yellow;
      g.globalAlpha = 0.55 + 0.45 * lit;
      g.fill();
      g.restore();
    }
  }

  // ---- 车头：黑从灯的四周长出来（压在光柱上） -------------------------
  const nose = smooth((t - 2.35) / 1.35);
  if (nose > 0) {
    const nw = lerp(120, 1080, nose);
    const nh = lerp(90, 900, nose);
    const ncx = LAMP.x - 6;
    const top = H + 40 - nh;
    const pts = [
      [ncx - nw / 2, H + 60], [ncx - nw / 2, top + 100], [ncx - nw / 2 + 26, top + 40],
      [ncx - nw / 2 + 132, top + 6], [ncx + nw / 2 - 132, top + 6], [ncx + nw / 2 - 26, top + 40],
      [ncx + nw / 2, top + 100], [ncx + nw / 2, H + 60],
    ];
    mass(g, pts, P, { amp: 2.8, step: 30, carve: 4.5, seed: 313 });
    // 车头正面的一道横沟 + 下面的排障器
    g.save();
    g.strokeStyle = P.paper;
    g.lineWidth = 3;
    g.globalAlpha = 0.85;
    g.beginPath();
    g.moveTo(ncx - nw / 2 + 40, top + 168);
    g.lineTo(ncx + nw / 2 - 40, top + 168);
    g.stroke();
    g.restore();
    if (nose > 0.42) {
      const bw = lerp(36, 330, (nose - 0.42) / 0.58);
      mass(g, [[ncx - bw / 2, top + 92], [ncx + bw / 2, top + 92], [ncx + bw / 2, top + 132], [ncx - bw / 2, top + 132]], P, {
        amp: 1.6, step: 18, carve: 2.6, seed: 315, fill: 'yellow',
      });
      g.save();
      g.strokeStyle = P.paper;
      g.lineWidth = 2;
      g.beginPath();
      g.moveTo(ncx - bw / 2 + 10, top + 112);
      g.lineTo(ncx + bw / 2 - 10, top + 112);
      g.stroke();
      g.restore();
    }
    // 两侧的小灯
    if (nose > 0.55) {
      for (const side of [-1, 1]) {
        g.fillStyle = P.yellow;
        g.beginPath();
        g.arc(ncx + side * nw * 0.3, top + 210, 9 + nose * 7, 0, Math.PI * 2);
        g.fill();
      }
    }
  }

  // ---- 灯本身：纸白的心，一圈点阵边（画在车头上，因为灯就在车头上） ----
  if (lit > 0) {
    const lr = 9 + 74 * lit;
    g.save();
    g.fillStyle = P.yellow;
    g.globalAlpha = 0.95;
    g.beginPath();
    g.arc(LAMP.x, LAMP.y, lr + 16, 0, Math.PI * 2);
    g.fill();
    g.fillStyle = P.paper;
    g.beginPath();
    g.arc(LAMP.x, LAMP.y, lr, 0, Math.PI * 2);
    g.fill();
    // 横向眩光：车灯是横的一道，不是一颗球
    g.fillStyle = P.paper;
    const gl = 90 + 430 * lit;
    for (let i = 0; i < 26; i++) {
      const t0 = i / 25;
      const w0 = (1 - t0) ** 1.6;
      g.globalAlpha = 0.55 * w0;
      g.fillRect(LAMP.x - gl * t0, LAMP.y - 5 * w0, gl * 0.045, 10 * w0);
      g.fillRect(LAMP.x + gl * t0, LAMP.y - 5 * w0, gl * 0.045, 10 * w0);
    }
    g.fillStyle = P.yellow;
    const n = 96;
    for (let i = 0; i < n; i++) {
      const a = (i / n) * Math.PI * 2;
      const rr = lr + 30 + Math.sin(i * 2.7) * 7;
      g.globalAlpha = 0.9;
      g.beginPath();
      g.arc(LAMP.x + Math.cos(a) * rr, LAMP.y + Math.sin(a) * rr, 4.4 + Math.sin(i * 1.9) * 1.4, 0, Math.PI * 2);
      g.fill();
    }
    g.restore();
  }

  // ---- 风声：洞外画墨，洞里画纸 --------------------------------------
  for (let i = 0; i < wind.length; i++) {
    const s = wind[i];
    const age = t - s.birth;
    if (age < 0) continue;
    const ph = (age * 0.46 + s.off * 0.4) % 1.3;
    const x = -60 + ph * 2200;
    const y = s.y + Math.sin(ph * 2.2 + i) * 16;
    const pts = windPath(x, y, s.len * (0.6 + ph * 0.7), 22, s.lift * (0.5 + ph));
    const dark = isWall(x + 120, y);
    windStroke(g, P, { pts, width: s.w * (0.6 + ph * 0.6), dark, alpha: 0.88 * clamp01(age / 0.4) });
  }

  // ---- 碎纸：被风顶着往右跑，穿过光 --------------------------------
  for (const d of debris) {
    const age = t - 0.55;
    if (age < 0) continue;
    const ph = (age * 0.42 * d.v + d.off) % 1.25;
    const x = -100 + ph * 2200;
    const y = d.y + Math.sin(ph * 5 + d.rot) * 40 - ph * 60;
    drawDebris(g, x, y, d.rot + ph * d.spin, d.s * (0.7 + 0.5 * Math.sin(ph * 3)));
  }

  // ---- 灰 ------------------------------------------------------------
  for (const m of motes) {
    const x = ((m.x + m.v * t) % (W + 200)) - 100;
    g.globalAlpha = m.a * (0.4 + 0.6 * smooth(t / 2.4));
    g.fillStyle = P.ink;
    g.beginPath();
    g.ellipse(x, m.y + Math.sin(t * 2 + m.x) * 8, m.s * 2.8, m.s * 1, 0.2, 0, Math.PI * 2);
    g.fill();
  }
  g.globalAlpha = 1;
  g.restore();
}
